import java.io.OutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.stream.IntStream;
import java.util.List;
import java.util.Arrays;
import java.util.InputMismatchException;
import java.io.IOException;
import java.util.ArrayList;
import java.io.InputStream;

/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskB solver = new TaskB();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskB {
        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int n = in.nextInt();
            int m = in.nextInt();
            if (n > m) {
                int t = n;
                n = m;
                m = t;
            }

            long V = (long) n * m;

            if (V < 100) {
                List<Integer>[] g = new List[(int) V];
                for (int i = 0; i < V; i++) {
                    g[i] = new ArrayList<>();
                }
                for (int i = 0; i < V; i++) {
                    for (int j = 0; j < V; j++) {
                        int r1 = i / m;
                        int c1 = i % m;
                        int r2 = j / m;
                        int c2 = j % m;
                        if (Math.abs(r1 - r2) + Math.abs(c1 - c2) == 3) {
                            g[i].add(j);
                        }
                    }
                }

                int res = maxMatching(g) * 2;
                out.println(res);
            } else {
                long res;
                if (n == 1) {
                    res = m / 6 * 6 + (m % 6 == 4 ? 2 : 0) + (m % 6 == 5 ? 4 : 0);
                } else {
                    res = (long) n * m;
                    res -= res % 2;
                }
                out.println(res);
            }
        }

        static int maxMatching(List<Integer>[] graph) {
            int n = graph.length;
            int[] match = new int[n];
            Arrays.fill(match, -1);
            int[] p = new int[n];
            for (int i = 0; i < n; ++i) {
                if (match[i] == -1) {
                    int v = findPath(graph, match, p, i);
                    while (v != -1) {
                        int pv = p[v];
                        int ppv = match[pv];
                        match[v] = pv;
                        match[pv] = v;
                        v = ppv;
                    }
                }
            }
            return (int) Arrays.stream(match).filter(x -> x != -1).count() / 2;
        }

        static int findPath(List<Integer>[] graph, int[] match, int[] p, int root) {
            Arrays.fill(p, -1);
            int n = graph.length;
            int[] base = IntStream.range(0, n).toArray();

            boolean[] used = new boolean[n];
            int[] q = new int[n];
            int qt = 0;
            used[root] = true;
            q[qt++] = root;
            for (int qh = 0; qh < qt; qh++) {
                int u = q[qh];
                for (int v : graph[u]) {
                    if (base[u] == base[v] || match[u] == v) continue;
                    if (v == root || match[v] != -1 && p[match[v]] != -1) {
                        int curbase = lca(match, base, p, u, v);
                        boolean[] blossom = new boolean[n];
                        markPath(match, base, blossom, p, u, curbase, v);
                        markPath(match, base, blossom, p, v, curbase, u);
                        for (int i = 0; i < n; ++i)
                            if (blossom[base[i]]) {
                                base[i] = curbase;
                                if (!used[i]) {
                                    used[i] = true;
                                    q[qt++] = i;
                                }
                            }
                    } else if (p[v] == -1) {
                        p[v] = u;
                        if (match[v] == -1)
                            return v;
                        v = match[v];
                        used[v] = true;
                        q[qt++] = v;
                    }
                }
            }
            return -1;
        }

        static void markPath(int[] match, int[] base, boolean[] blossom, int[] p, int u, int curbase, int child) {
            for (; base[u] != curbase; u = p[match[u]]) {
                blossom[base[u]] = blossom[base[match[u]]] = true;
                p[u] = child;
                child = match[u];
            }
        }

        static int lca(int[] match, int[] base, int[] p, int a, int b) {
            boolean[] used = new boolean[match.length];
            while (true) {
                a = base[a];
                used[a] = true;
                if (match[a] == -1) break;
                a = p[match[a]];
            }
            while (true) {
                b = base[b];
                if (used[b]) return b;
                b = p[match[b]];
            }
        }

    }

    static class InputReader {
        final InputStream is;
        final byte[] buf = new byte[1024];
        int pos;
        int size;

        public InputReader(InputStream is) {
            this.is = is;
        }

        public int nextInt() {
            int c = read();
            while (isWhitespace(c))
                c = read();
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9')
                    throw new InputMismatchException();
                res = res * 10 + c - '0';
                c = read();
            } while (!isWhitespace(c));
            return res * sign;
        }

        int read() {
            if (size == -1)
                throw new InputMismatchException();
            if (pos >= size) {
                pos = 0;
                try {
                    size = is.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (size <= 0)
                    return -1;
            }
            return buf[pos++] & 255;
        }

        static boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

    }
}


